const nl = String.fromCharCode(10);
const body = $json.body || $json;
const msg = body.messages && body.messages[0];
if (!msg) return [];
if (body.event && body.event !== 'whatsapp.message.received') return [];

const raw = (msg.text && msg.text.body || '').trim();
const text = raw.toLowerCase();
const from = msg.from || body.from;

const store = $getWorkflowStaticData('global');
store.registros = store.registros || {};
store.reservas = store.reservas || {};
const usuario = store.registros[from] || '';

let intent = 'desconocido';
let payloadStr = '';

if (['hola','hi','ayuda','start','/start','menu','beca','mis reservas','reservas','estado','quien soy','yo'].indexOf(text) !== -1 ||
    text.startsWith('soy ') || text.startsWith('reservar')) {
  if (text === 'hola' || text === 'hi' || text === 'ayuda' || text === 'start' || text === '/start') {
    intent = usuario ? 'bienvenida' : 'pedir_registro';
  } else if (text.startsWith('soy ')) {
    intent = 'registrar';
    payloadStr = raw.split(' ').slice(1).join(' ').trim();
  } else if (text === 'quien soy' || text === 'yo') {
    intent = 'quien_soy';
  } else if (text === 'menu') {
    intent = usuario ? 'menu' : 'pedir_registro_menu';
  } else if (text === 'beca' || text === 'mi beca') {
    intent = usuario ? 'beca' : 'pedir_registro';
  } else if (text === 'mis reservas' || text === 'reservas' || text === 'estado') {
    intent = usuario ? 'mis_reservas' : 'pedir_registro';
  } else if (text.startsWith('reservar')) {
    const plato = raw.replace(/^reservar\s*/i,'').trim();
    if (!usuario) intent = 'pedir_registro';
    else if (!plato) intent = 'reservar_sin_plato';
    else { intent = 'reservar'; payloadStr = plato; }
  }
} else {
  intent = 'desconocido';
}

return [{ json: { intent, from, usuario, payloadStr, text: raw } }];

const nl = String.fromCharCode(10);
const prev = $('Parse').first().json;
const menus = $json;
const arr = Array.isArray(menus) ? menus : (menus.data || []);
if (!arr || arr.length === 0) return [{ json: { to: prev.from, text: 'No hay menu publicado hoy.' } }];
const byPlato = {};
for (const m of arr) {
  const porc = m.porciones || {};
  const keys = Object.keys(porc);
  for (let i=0; i<keys.length; i++) {
    const id = keys[i], p = porc[id];
    const prevP = byPlato[id];
    if (!prevP || p.disponibles > prevP.disponibles) {
      byPlato[id] = { disponibles: p.disponibles, cupo: p.cupo, fecha: m.fecha };
    }
  }
}
const lines = Object.keys(byPlato).map(id => {
  const p = byPlato[id];
  return '- ' + id + ': ' + p.disponibles + '/' + p.cupo + ' (' + p.fecha + ')';
});
const text = 'Menu ALMUERZO esta semana:' + nl + lines.join(nl) + nl + nl + 'Para reservar: reservar <platoId>';
return [{ json: { to: prev.from, text } }];

const nl = String.fromCharCode(10);
const prev = $('Parse').first().json;
const b = $json;
if (!b || !b.tieneBeca) {
  const t = 'Tu usuario *' + prev.usuario + '* NO tiene beca activa.' + nl + nl +
    'Debes pagar Bs 10 con QR al reservar.' + nl + 'Escribi: reservar <platoId>';
  return [{ json: { to: prev.from, text: t } }];
}
const t = 'Beca *' + (b.tipo || 'standard') + '* activa.' + nl +
  'Raciones mes: ' + (b.racionesUsadasMes || 0) + ' / ' + (b.cupoRacionesMes || 0) + nl +
  (b.cubreHoy ? 'Hoy la beca cubre tu racion.' : 'Hoy pagas con QR (cupo agotado).');
return [{ json: { to: prev.from, text: t } }];

const prev = $('Parse').first().json;
const menus = $json;
const arr = Array.isArray(menus) ? menus : (menus.data || []);
const platoId = prev.payloadStr;
let best = null;
for (let i=0; i<arr.length; i++) {
  const m = arr[i];
  const p = (m.porciones || {})[platoId];
  if (p && p.disponibles > 0) {
    if (!best || p.disponibles > best.p.disponibles) best = { m, p };
  }
}
if (!best) return [{ json: { to: prev.from, text: 'No hay cupos para *' + platoId + '*.', bypass: true } }];
return [{ json: {
  to: prev.from, bypass: false,
  usuario: prev.usuario, platoId,
  menuId: best.m.id, fecha: best.m.fecha
} }];

const nl = String.fromCharCode(10);
const pick = $('Pick plato').first().json;
if (pick.bypass) return [{ json: { to: pick.to, text: pick.text } }];
const r = $json;
const from = pick.to;
const store = $getWorkflowStaticData('global');
store.reservas = store.reservas || {};
store.reservas[from] = store.reservas[from] || [];
store.reservas[from].unshift({
  reservaId: r.reservaId, plato: pick.platoId, fecha: pick.fecha,
  status: r.status, ts: Date.now(),
  paymentUrl: r.stripe && r.stripe.paymentUrl
});
if (store.reservas[from].length > 20) store.reservas[from] = store.reservas[from].slice(0, 20);
if (r.stripe && r.stripe.paymentUrl) {
  const t = 'Reserva creada!' + nl +
    'ID: ' + (r.reservaId||'').slice(0, 10) + '...' + nl +
    'Plato: ' + pick.platoId + nl +
    'Fecha: ' + pick.fecha + nl + nl +
    'Paga con Stripe:' + nl + r.stripe.paymentUrl + nl + nl +
    'Tarjeta test: 4242 4242 4242 4242' + nl +
    'Despues: mis reservas';
  return [{ json: { to: from, text: t } }];
}
return [{ json: { to: from, text: 'Reserva ' + (r.reservaId||'').slice(0,10) + ' estado ' + r.status } }];

const nl = String.fromCharCode(10);
const d = $json;
const i = d.intent;
let text = '';
const store = $getWorkflowStaticData('global');
store.registros = store.registros || {};
store.reservas = store.reservas || {};

if (i === 'registrar') {
  const u = d.payloadStr;
  if (!u) { text = 'Decime tu usuario asi: soy <tu_usuario>'; }
  else {
    store.registros[d.from] = u;
    text = 'Listo! Te registre como *' + u + '*.' + nl + nl +
      'Ahora podes: menu / beca / reservar <platoId> / mis reservas';
  }
} else if (i === 'quien_soy') {
  text = d.usuario ? 'Estas como: *' + d.usuario + '*' : 'Aun no te registraste. Escribi: soy <tu_usuario>';
} else if (i === 'bienvenida') {
  text = 'Comedor UAGRM — estas como *' + d.usuario + '*' + nl +
    'Comandos:' + nl + '- menu' + nl + '- beca' + nl + '- reservar <platoId>' + nl +
    '- mis reservas' + nl + '- soy <usuario>' + nl + '- quien soy';
} else if (i === 'pedir_registro') {
  text = 'Hola! Soy el bot del Comedor UAGRM.' + nl + nl +
    'Para empezar decime tu usuario asi:' + nl + '*soy estudiante.demo*' + nl + nl +
    'Despues podras: menu, beca, reservar <plato>, mis reservas.';
} else if (i === 'pedir_registro_menu') {
  text = 'Primero decime quien sos: soy <tu_usuario>' + nl + 'Despues escribi: menu';
} else if (i === 'mis_reservas') {
  const mias = store.reservas[d.from] || [];
  if (mias.length === 0) text = 'Aun no reservaste nada. Escribi: reservar <platoId>';
  else {
    const lines = mias.slice(0, 5).map((r, idx) =>
      (idx+1) + '. ' + r.plato + ' - ' + r.fecha + ' - ' + (r.status||'pendiente'));
    text = 'Tus ultimas reservas (' + d.usuario + '):' + nl + lines.join(nl);
  }
} else if (i === 'reservar_sin_plato') {
  text = 'Faltan datos: reservar <platoId>. Ej: reservar plato-asado';
} else {
  text = 'No entiendo. Comandos:' + nl +
    '- hola / ayuda' + nl + '- soy <usuario>' + nl + '- menu' + nl + '- beca' + nl +
    '- reservar <platoId>' + nl + '- mis reservas' + nl + '- quien soy';
}
return [{ json: { to: d.from, text } }];
